CREATE SCHEMA IF NOT EXISTS auth;
-- Stub of Supabase's built-in auth.users so user_id foreign keys resolve
CREATE TABLE IF NOT EXISTS auth.users (
    id uuid PRIMARY KEY
);

CREATE TABLE admin_audit_log (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    admin_id uuid,
    event_type text NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE daily_water (
    user_id uuid NOT NULL,
    date date NOT NULL,
    water_ml numeric DEFAULT 0 NOT NULL
);

CREATE TABLE day_logs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    date date NOT NULL,
    food_id uuid NOT NULL,
    logged_quantity numeric DEFAULT 0 NOT NULL,
    contributed_quantity numeric DEFAULT 0 NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE foods (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    name text NOT NULL,
    emoji text DEFAULT 'Utensils'::text NOT NULL,
    target_quantity numeric DEFAULT 1 NOT NULL,
    unit text DEFAULT 'count'::text NOT NULL,
    calories numeric DEFAULT 0 NOT NULL,
    protein numeric DEFAULT 0 NOT NULL,
    carbs numeric DEFAULT 0 NOT NULL,
    fats numeric DEFAULT 0 NOT NULL,
    aliases text[] DEFAULT '{}'::text[] NOT NULL,
    sort_order integer DEFAULT 0 NOT NULL,
    archived boolean DEFAULT false NOT NULL,
    kind text DEFAULT 'quantity'::text NOT NULL,
    active_days smallint[] DEFAULT '{0,1,2,3,4,5,6}'::smallint[] NOT NULL,
    active_date date,
    category text DEFAULT 'other'::text NOT NULL,
    custom_category text DEFAULT ''::text NOT NULL,
    base_ingredient text DEFAULT ''::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT foods_category_chk CHECK ((category = ANY (ARRAY['protein'::text, 'grain'::text, 'vegetable'::text, 'fruit'::text, 'dairy'::text, 'fat'::text, 'custom'::text, 'other'::text]))),
    CONSTRAINT foods_kind_chk CHECK ((kind = ANY (ARRAY['binary'::text, 'quantity'::text]))),
    CONSTRAINT foods_unit_chk CHECK ((unit = ANY (ARRAY['g'::text, 'ml'::text, 'serving'::text, 'count'::text, 'oz'::text])))
);

CREATE TABLE meal_combo_items (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    combo_id uuid NOT NULL,
    user_id uuid NOT NULL,
    food_id uuid,
    recent_food_id uuid,
    quantity numeric DEFAULT 0 NOT NULL,
    sort_order integer DEFAULT 0 NOT NULL,
    CONSTRAINT meal_combo_items_exactly_one_ref CHECK (((food_id IS NULL) <> (recent_food_id IS NULL)))
);

CREATE TABLE meal_combos (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    name text NOT NULL,
    icon text DEFAULT 'UtensilsCrossed'::text NOT NULL,
    sort_order integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE milestones (
    user_id uuid NOT NULL,
    key text NOT NULL,
    achieved_at date DEFAULT CURRENT_DATE NOT NULL
);

CREATE TABLE password_otp_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    email text NOT NULL,
    purpose text NOT NULL,
    user_id uuid,
    code_hash text NOT NULL,
    code_salt text NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    max_attempts integer DEFAULT 5 NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    verify_token_hash text,
    verify_expires_at timestamp with time zone,
    consumed boolean DEFAULT false NOT NULL,
    last_sent_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT password_otp_requests_purpose_check CHECK ((purpose = ANY (ARRAY['change_password'::text, 'set_password'::text, 'forgot_password'::text, 'signup_verify'::text])))
);

CREATE TABLE product_catalogue (
