    discount_paise bigint DEFAULT 0 NOT NULL,
    delivery_paise bigint DEFAULT 0 NOT NULL,
    total_paise bigint DEFAULT 0 NOT NULL,
    status text DEFAULT 'placed'::text NOT NULL,
